import{_ as t,o as i,c as e,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"SWITCH- Operations, Data Management and Automation - Theophilos Mouratidis, SWITCH","description":"","frontmatter":{"title":"SWITCH- Operations, Data Management and Automation - Theophilos Mouratidis, SWITCH","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["Ceph","Distributed Storage","Automation","DevOps","GitOps"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/SWITCH_-_Operations_Data_Management_and_Automation_-_Theofilos_Mouratidis_SWITCH.md","filePath":"posts/2025/SWITCH_-_Operations_Data_Management_and_Automation_-_Theofilos_Mouratidis_SWITCH.md","lastUpdated":1780459816000}'),l={name:"posts/2025/SWITCH_-_Operations_Data_Management_and_Automation_-_Theofilos_Mouratidis_SWITCH.md"};function r(n,a,s,h,p,u){return i(),e("div",null,[...a[0]||(a[0]=[o('<h3 id="会议纪要-switch团队在ceph存储系统中的实践与创新" tabindex="-1">会议纪要：Switch团队在Ceph存储系统中的实践与创新 <a class="header-anchor" href="#会议纪要-switch团队在ceph存储系统中的实践与创新" aria-label="Permalink to &quot;会议纪要：Switch团队在Ceph存储系统中的实践与创新&quot;">​</a></h3><p><strong>会议主题</strong>：Switch团队在Ceph存储系统中的应用与自动化部署实践</p><p><strong>主讲人</strong>：Theos Moris，Switch团队的Ceph工程师</p><p><strong>会议内容总结</strong>：</p><h4 id="_1-switch团队背景" tabindex="-1">1. <strong>Switch团队背景</strong> <a class="header-anchor" href="#_1-switch团队背景" aria-label="Permalink to &quot;1. **Switch团队背景**&quot;">​</a></h4><ul><li>Switch是瑞士的国家研究与教育网络（NREN），负责提供IT服务，包括云计算、网络安全和法律服务等。</li><li>Switch团队专注于存储解决方案，主要使用Ceph。</li></ul><h4 id="_2-存储解决方案" tabindex="-1">2. <strong>存储解决方案</strong> <a class="header-anchor" href="#_2-存储解决方案" aria-label="Permalink to &quot;2. **存储解决方案**&quot;">​</a></h4><ul><li><strong>传统系统</strong>：基于Ceph的对象存储版本1和基于Claudian Hyperstore的对象存储版本2。</li><li><strong>新系统</strong>： <ul><li><strong>Object Store v3</strong>：基于Ceph，为Switch Cloud平台提供S3服务。</li><li><strong>Switch Cloud Portal</strong>：提供计算、S3和Kubernetes等服务。</li></ul></li></ul><h4 id="_3-ceph集群的规模与升级" tabindex="-1">3. <strong>Ceph集群的规模与升级</strong> <a class="header-anchor" href="#_3-ceph集群的规模与升级" aria-label="Permalink to &quot;3. **Ceph集群的规模与升级**&quot;">​</a></h4><ul><li>现有多个Ceph集群，总容量约20PB。</li><li>最近从Ceph Octopus升级到Ceph 17版本，支持全IPv6。</li><li>新集群Albinia和BN已部署，正在进行实验和优化。</li></ul><h4 id="_4-ceph与claudian的对比" tabindex="-1">4. <strong>Ceph与Claudian的对比</strong> <a class="header-anchor" href="#_4-ceph与claudian的对比" aria-label="Permalink to &quot;4. **Ceph与Claudian的对比**&quot;">​</a></h4><ul><li>Ceph更灵活、可扩展，能够进行复杂的升级和替换。</li><li>Claudian容量有限，扩展和替换困难，升级过程复杂且耗时。</li><li>团队正在将数据从Claudian迁移回Ceph。</li></ul><h4 id="_5-devops与gitops实践" tabindex="-1">5. <strong>DevOps与GitOps实践</strong> <a class="header-anchor" href="#_5-devops与gitops实践" aria-label="Permalink to &quot;5. **DevOps与GitOps实践**&quot;">​</a></h4><ul><li>传统DevOps使用脚本进行配置管理，存在配置不一致的问题。</li><li>GitOps通过Git作为单一的事实来源，确保配置的一致性和持续交付。</li><li>使用Ansible、Terraform和Makefile进行自动化部署。</li></ul><h4 id="_6-ceph自动化部署工具" tabindex="-1">6. <strong>Ceph自动化部署工具</strong> <a class="header-anchor" href="#_6-ceph自动化部署工具" aria-label="Permalink to &quot;6. **Ceph自动化部署工具**&quot;">​</a></h4><ul><li><strong>OSv3 Ansible Collection</strong>：基于Red Hat的Ceph Ansible Collection，Switch团队进行了大量定制。</li><li>每个角色只负责单一任务，确保代码的模块化和可维护性。</li><li>配置管理仓库包含集群特定的信息，支持多种操作。</li></ul><h4 id="_7-多站点部署" tabindex="-1">7. <strong>多站点部署</strong> <a class="header-anchor" href="#_7-多站点部署" aria-label="Permalink to &quot;7. **多站点部署**&quot;">​</a></h4><ul><li>支持多站点集群的自动化部署，确保数据在不同站点之间的复制和同步。</li><li>使用GitLab CI/CD进行自动化部署。</li></ul><h4 id="_8-switch-cloud-portal" tabindex="-1">8. <strong>Switch Cloud Portal</strong> <a class="header-anchor" href="#_8-switch-cloud-portal" aria-label="Permalink to &quot;8. **Switch Cloud Portal**&quot;">​</a></h4><ul><li>提供多租户支持，用户可以通过UI管理计算、S3和Kubernetes服务。</li><li>集成Ceph的RGW Admin API，支持S3服务的创建和管理。</li></ul><h4 id="_9-未来计划" tabindex="-1">9. <strong>未来计划</strong> <a class="header-anchor" href="#_9-未来计划" aria-label="Permalink to &quot;9. **未来计划**&quot;">​</a></h4><ul><li>计划将OSv3 Ansible Collection开源。</li><li>继续优化自动化部署流程，增加更多功能。</li></ul><h4 id="_10-问答环节" tabindex="-1">10. <strong>问答环节</strong> <a class="header-anchor" href="#_10-问答环节" aria-label="Permalink to &quot;10. **问答环节**&quot;">​</a></h4><ul><li>使用标签而非组，因为标签可以在同一组中灵活添加和删除，避免代码维护的复杂性。</li></ul><p><strong>会议总结</strong>： Switch团队在Ceph存储系统的应用中，通过GitOps和自动化工具实现了高效的集群管理和部署。未来，团队计划将这些工具开源，以帮助更多Ceph用户简化部署流程。</p>',25)])])}const c=t(l,[["render",r]]);export{d as __pageData,c as default};
